func SourceHasSuffix(v string) predicate.MarketData {
	return predicate.MarketData(sql.FieldHasSuffix(FieldSource, v))
}

// SourceEqualFold applies the EqualFold predicate on the "source" field.
func SourceEqualFold(v string) predicate.MarketData {
	return predicate.MarketData(sql.FieldEqualFold(FieldSource, v))
}

// SourceContainsFold applies the ContainsFold predicate on the "source" field.
func SourceContainsFold(v string) predicate.MarketData {
	return predicate.MarketData(sql.FieldContainsFold(FieldSource, v))
}

// And groups predicates with the AND operator between them.
func And(predicates ...predicate.MarketData) predicate.MarketData {
	return predicate.MarketData(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.MarketData) predicate.MarketData {
	return predicate.MarketData(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.MarketData) predicate.MarketData {
	return predicate.MarketData(sql.NotPredicates(p))
}
